  /**
   * @method
   * @name extended#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for all markets
   * @see https://api.docs.extended.exchange/#get-markets
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<std::any>
  fetchTickers(std::any symbols = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarkets());
                 symbols = this->marketSymbols(symbols);
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbols, std::any{}))) {
                   std::any marketIds = ccxt::list{};
                   for (std::any i = 0; isLessThan(i, getArrayLength(symbols));
                        postFixIncrement(i)) {
                     std::any market = this->market(::getValue(symbols, i));
                     arrayPush(marketIds,
                               ::getValue(market, std::string("id")));
                   }
                   ::setValue(request, std::string("market"), marketIds);
                 }
                 std::any response = awaitValue(this->v1PublicGetInfoMarkets(
                     this->extend(request, params)));
                 //
                 //     {
                 //       "status": "OK",
                 //       "data": [
                 //         {
                 //           "name": "BTC-USD",
                 //           "assetName": "BTC",
                 //           "collateralAssetName": "USD",
                 //           "marketStats": {
                 //             "dailyVolume": "231016077.512960",
                 //             ...
                 //           },
                 //           ...
                 //         }
                 //       ]
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 std::any tickers = ccxt::dict{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any marketData = ::getValue(data, i);
                   std::any marketId =
                       this->safeString(marketData, std::string("name"));
                   std::any market = this->safeMarket(marketId);
                   std::any stats = this->safeDict(
                       marketData, std::string("marketStats"), ccxt::dict{});
                   std::any ticker = this->parseTicker(stats, market);
                   std::any symbol = ::getValue(ticker, std::string("symbol"));
                   if (isTrue(!isEqual(symbol, std::any{}))) {
                     ::setValue(tickers, symbol, ticker);
                   }
                 }
                 return this->filterByArrayTickers(
                     tickers, std::string("symbol"), symbols);
               })
        .share();
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    //
    //     {
    //       "dailyVolume": "231216165.666600",
    //       "dailyVolumeBase": "3027.36710",
    //       "dailyPriceChange": "181",
    //       "dailyPriceChangePercentage": "0.0024",
    //       "dailyLow": "75635",
    //       "dailyHigh": "77399",
    //       "lastPrice": "77026",
    //       "askPrice": "77026",
    //       "bidPrice": "77025",
    //       "markPrice": "77006.091897999984",
    //       "indexPrice": "77050.739529925005",
    //       "fundingRate": "0.000012",
    //       "nextFundingRate": 1777446000000,
    //       "openInterest": "114851569.088316",
    //       "openInterestBase": "1491.33012",
    //       "deleverageLevels": {
    //         "shortPositions": [
    //           { "level": 1, "rankingLowerBound": "-784.2884" },
    //           { "level": 2, "rankingLowerBound": "-2.1078" },
    //           { "level": 3, "rankingLowerBound": "-0.8754" },
    //           { "level": 4, "rankingLowerBound": "0.0000" }
    //         ],
    //         "longPositions": [
    //           { "level": 1, "rankingLowerBound": "-47747.2010" },
    //           { "level": 2, "rankingLowerBound": "-0.0131" },
    //           { "level": 3, "rankingLowerBound": "0.0019" },
    //           { "level": 4, "rankingLowerBound": "0.0032" }
    //         ]
    //       }
    //     }
    //
    std::any symbol = this->safeSymbol(std::any{}, market);
    std::any last = this->safeNumber(ticker, std::string("lastPrice"));
    std::any percentageRaw =
        this->safeString(ticker, std::string("dailyPriceChangePercentage"));
    std::any percentage = (isTrue((!isEqual(percentageRaw, std::any{})))
                               ? std::any(ccxt::Precise::stringMul(
                                     percentageRaw, std::string("100")))
                               : std::any(std::any{}));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), std::any{}},
            {std::string("datetime"), std::any{}},
            {std::string("high"),
             this->safeNumber(ticker, std::string("dailyHigh"))},
            {std::string("low"),
             this->safeNumber(ticker, std::string("dailyLow"))},
            {std::string("bid"),
             this->safeNumber(ticker, std::string("bidPrice"))},
            {std::string("bidVolume"), std::any{}},
            {std::string("ask"),
             this->safeNumber(ticker, std::string("askPrice"))},
            {std::string("askVolume"), std::any{}},
            {std::string("vwap"), std::any{}},
            {std::string("open"), std::any{}},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), std::any{}},
            {std::string("change"),
             this->safeNumber(ticker, std::string("dailyPriceChange"))},
            {std::string("percentage"), percentage},
            {std::string("average"), std::any{}},
            {std::string("baseVolume"),
             this->safeNumber(ticker, std::string("dailyVolumeBase"))},
            {std::string("quoteVolume"),
             this->safeNumber(ticker, std::string("dailyVolume"))},
            {std::string("markPrice"),
             this->safeNumber(ticker, std::string("markPrice"))},
            {std::string("indexPrice"),
             this->safeNumber(ticker, std::string("indexPrice"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name extended#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://api.docs.extended.exchange/#get-market-order-book
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarkets());
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("market"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response =
                     awaitValue(this->v1PublicGetInfoMarketsMarketOrderbook(
                         this->extend(request, params)));
                 //
                 //     {
                 //       "status": "OK",
                 //       "data": {
                 //         "market": "BTC-USD",
                 //         "bid": [
                 //           {
                 //             "qty": "14.46084",
                 //             "price": "76214"
                 //           }
                 //         ],
                 //         "ask": [
                 //           {
                 //             "qty": "0.11585",
                 //             "price": "76215"
                 //           }
                 //         ]
                 //       }
                 //     }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any timestamp = this->milliseconds();
                 std::any orderbook = this->parseOrderBook(
                     data, ::getValue(market, std::string("symbol")), timestamp,
                     std::string("bid"), std::string("ask"),
                     std::string("price"), std::string("qty"));
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(orderbook, std::string("bids"),
                              this->arraySlice(
                                  ::getValue(orderbook, std::string("bids")), 0,
                                  limit));
                   ::setValue(orderbook, std::string("asks"),
                              this->arraySlice(
                                  ::getValue(orderbook, std::string("asks")), 0,
                                  limit));
                 }
                 return orderbook;
               })
        .share();
  }

