  /**
   * @method
   * @name extended#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://api.docs.extended.exchange/#get-trades
   * @param {string} [symbol] unified market symbol of the trades
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trade structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<std::any>
  fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{},
                std::any limit = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 awaitValue(this->loadMarkets());
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallCursor(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params, std::string("cursor"), std::string("cursor"),
                       std::any{}, 100));
                 }
                 std::any market = std::any{};
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response = awaitValue(this->v1PrivateGetUserTrades(
                     this->extend(params, request)));
                 //
                 //     {
                 //         "status": "OK",
                 //         "data": [
                 //             {
                 //                 "id": 1,
                 //                 "orderId": 1784980437895231232,
                 //                 "externalId": "ExtId-1",
                 //                 "accountId": 1,
                 //                 "market": "BTC-USD",
                 //                 "side": "BUY",
                 //                 "price": "39000",
                 //                 "qty": "0.2",
                 //                 "value": "7800",
                 //                 "fee": "1.3",
                 //                 "tradeType": "TRADE",
                 //                 "isTaker": true,
                 //                 "createdTime": 1701563440000
                 //             }
                 //         ],
                 //         "pagination": {
                 //             "cursor": 1784963886257016832,
                 //             "count": 1
                 //         }
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 std::any pagination = this->safeDict(
                     response, std::string("pagination"), ccxt::dict{});
                 std::any cursor =
                     this->safeString(pagination, std::string("cursor"));
                 std::any result = ccxt::list{};
                 std::any dataLength = getArrayLength(data);
                 for (std::any i = 0; isLessThan(i, dataLength);
                      postFixIncrement(i)) {
                   std::any entry = ::getValue(data, i);
                   if (isTrue(isTrue((!isEqual(cursor, std::any{}))) &&
                              isTrue((isEqual(i, subtract(dataLength, 1)))))) {
                     entry = this->extend(entry,
                                          ccxt::dict{
                                              {std::string("cursor"), cursor},
                                          });
                   }
                   arrayPush(result, entry);
                 }
                 return this->parseTrades(result, market, since, limit);
               })
        .share();
  }

