                        //                 "notionalValue": "13500",
                        //                 "contributionFactor": "1",
                        //                 "equityContribution": "13500",
                        //                 "availableToWithdraw": "100",
                        //                 "updatedAt": 1701563440
                        //             },
                        //             {
                        //                 "accountId": 123,
                        //                 "asset": "BTC",
                        //                 "balance": "0.5",
                        //                 "indexPrice": "65000",
                        //                 "notionalValue": "32500",
                        //                 "contributionFactor": "0.95",
                        //                 "equityContribution": "30875",
                        //                 "availableToWithdraw": "0.5",
                        //                 "updatedAt": 1701563440
                        //             }
                        //         ]
                        //     }
